mapper.select:
SELECT bi.item_id, bi.item_code, bi.item_name, COALESCE(bi.budget_year, b.budget_year) as budget_year, bc.category_type, bs.subject_id, bs.subject_code, bs.subject_name, COALESCE(MAX(b.budget_amount), 0) as budget_amount, -- 使用detail_type字段判断：PAYOUT为执行，APPLY为申请 COALESCE(SUM(CASE WHEN bdr.detail_type = 'PAYOUT' THEN bdr.amount ELSE 0 END), 0) as executed_amount, COALESCE(SUM(CASE WHEN bdr.detail_type = 'APPLY' THEN bdr.amount ELSE 0 END), 0) as applied_amount, -- 剩余可执行金额计算：预算总额 - 申请金额 - (执行金额 - 来自引用申请单的报账单的执行金额) -- 如果报账单引用申请单，执行金额不影响剩余金额，剩余金额 = 预算总额 - 申请金额 -- 如果报账单没有引用申请单，剩余金额 = 预算总额 - 申请金额 - 执行金额 COALESCE(MAX(b.budget_amount), 0) - COALESCE(SUM(CASE WHEN bdr.detail_type = 'APPLY' THEN bdr.amount ELSE 0 END), 0) - COALESCE(SUM(CASE WHEN bdr.detail_type = 'PAYOUT' AND (p.source_apply_no IS NULL OR p.source_apply_no = '') THEN bdr.amount ELSE 0 END), 0) as remaining_amount FROM budget_item bi LEFT JOIN budget_category bc ON bi.category_id = bc.category_id LEFT JOIN budget_item_subject bis ON bi.item_id = bis.item_id LEFT JOIN budget_subject bs ON bis.subject_id = bs.subject_id LEFT JOIN budget b ON bi.item_id = b.item_id AND bs.subject_id = b.subject_id LEFT JOIN budget_detail bdr ON b.subject_id = bdr.subject_id AND b.item_id = bdr.item_id LEFT JOIN ctrl_payout p ON p.payout_billcode = bdr.business_no WHERE 1=1
AND bs.subject_id = #{subjectId}
AND (bi.budget_year = #{budgetYear} OR b.budget_year = #{budgetYear})
AND bc.category_type = #{categoryType}
AND bi.item_name LIKE CONCAT('%', #{itemName}, '%')
GROUP BY bi.item_id, bi.item_code, bi.item_name, bi.budget_year, b.budget_year, bc.category_type, bs.subject_id, bs.subject_code, bs.subject_name ORDER BY COALESCE(bi.budget_year, b.budget_year) DESC, bi.item_name

SELECT bi.item_id, bi.item_code, bi.item_name, COALESCE(bi.budget_year, b.budget_year) as budget_year, bc.category_type, bs.subject_id, bs.subject_code, bs.subject_name, COALESCE(MAX(b.budget_amount), 0) as budget_amount, -- 使用detail_type字段判断：PAYOUT为执行，APPLY为申请 COALESCE(SUM(CASE WHEN bdr.detail_type = 'PAYOUT' THEN bdr.amount ELSE 0 END), 0) as executed_amount, COALESCE(SUM(CASE WHEN bdr.detail_type = 'APPLY' THEN bdr.amount ELSE 0 END), 0) as applied_amount, -- 剩余可执行金额计算：预算总额 - 申请金额 - (执行金额 - 来自引用申请单的报账单的执行金额) -- 如果报账单引用申请单，执行金额不影响剩余金额，剩余金额 = 预算总额 - 申请金额 -- 如果报账单没有引用申请单，剩余金额 = 预算总额 - 申请金额 - 执行金额 COALESCE(MAX(b.budget_amount), 0) - COALESCE(SUM(CASE WHEN bdr.detail_type = 'APPLY' THEN bdr.amount ELSE 0 END), 0) - COALESCE(SUM(CASE WHEN bdr.detail_type = 'PAYOUT' AND (p.source_apply_no IS NULL OR p.source_apply_no = '') THEN bdr.amount ELSE 0 END), 0) as remaining_amount FROM budget_item bi LEFT JOIN budget_category bc ON bi.category_id = bc.category_id LEFT JOIN budget_item_subject bis ON bi.item_id = bis.item_id LEFT JOIN budget_subject bs ON bis.subject_id = bs.subject_id LEFT JOIN budget b ON bi.item_id = b.item_id AND bs.subject_id = b.subject_id LEFT JOIN budget_detail bdr ON b.subject_id = bdr.subject_id AND b.item_id = bdr.item_id LEFT JOIN ctrl_payout p ON p.payout_billcode = bdr.business_no WHERE 1=1
AND bs.subject_id = #{subjectId}
AND (bi.budget_year = #{budgetYear} OR b.budget_year = #{budgetYear})
AND bc.category_type = #{categoryType}
AND bi.item_name LIKE CONCAT('%', #{itemName}, '%')
GROUP BY bi.item_id, bi.item_code, bi.item_name, bi.budget_year, b.budget_year, bc.category_type, bs.subject_id, bs.subject_code, bs.subject_name ORDER BY COALESCE(bi.budget_year, b.budget_year) DESC, bi.item_name LIMIT #{offset}, #{size}

SELECT COUNT(DISTINCT CONCAT(bi.item_id, '_', bs.subject_id)) FROM budget_item bi LEFT JOIN budget_category bc ON bi.category_id = bc.category_id LEFT JOIN budget_item_subject bis ON bi.item_id = bis.item_id LEFT JOIN budget_subject bs ON bis.subject_id = bs.subject_id LEFT JOIN budget b ON bi.item_id = b.item_id AND bs.subject_id = b.subject_id WHERE 1=1
AND bs.subject_id = #{subjectId}
AND (bi.budget_year = #{budgetYear} OR b.budget_year = #{budgetYear})
AND bc.category_type = #{categoryType}
AND bi.item_name LIKE CONCAT('%', #{itemName}, '%')
